import{_ as i,a0 as a,w as o,s as l,I as s,x as t,a1 as n,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份 | LCTT x X-CMD","titleTemplate":false,"description":"LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份 | LCTT (LFCS) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份 | LCTT (LFCS) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups","title":"LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份","tag":"LFCS","desc":""},"relativePath":"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups.md","filePath":"[post].md"}'),m={name:"LFCS/Part 6 - LFCS--Assembling Partitions as RAID Devices – Creating & Managing System Backups.md"};function g(u,e,c,v,A,b){const d=a("Link");return o(),l("div",null,[e[21]||(e[21]=s("h1",{id:"lfcs-系列第六講-組裝分區為raid設備——創建和管理系統備份",tabindex:"-1"},[t("LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份 "),s("a",{class:"header-anchor",href:"#lfcs-系列第六講-組裝分區為raid設備——創建和管理系統備份","aria-label":"Permalink to “LFCS 系列第六講：組裝分區為RAID設備——創建和管理系統備份”"},"​")],-1)),e[22]||(e[22]=s("p",null,"Linux 基金會已經發起了一個全新的 LFCS（Linux Foundation Certified Sysadmin，Linux 基金會認證系統管理員）認證，旨在讓來自世界各地的人有機會參加到 LFCS 測試，獲得關於有能力在 Linux 系統中執行中級系統管理任務的認證。該認證包括：維護正在運行的系統和服務的能力、全面監控和分析的能力以及何時向上遊團隊請求支持的決策能力。",-1)),e[23]||(e[23]=s("p",null,[s("img",{src:"http://www.tecmint.com/wp-content/uploads/2014/10/lfcs-Part-6.png",alt:"Linux Foundation Certified Sysadmin – Part 6"})],-1)),e[24]||(e[24]=s("p",null,[s("em",null,"LFCS 系列第六講")],-1)),e[25]||(e[25]=s("p",null,"以下視頻介紹了 Linux 基金會認證程序。",-1)),e[26]||(e[26]=s("p",null,"注：youtube 視頻",-1)),e[27]||(e[27]=s("iframe",{width:"720",height:"405",frameborder:"0",allowfullscreen:"allowfullscreen",src:"//www.youtube.com/embed/Y29qZ71Kicg"},null,-1)),e[28]||(e[28]=s("p",null,"本講是系列教程中的第六講，在這一講裏，我們將會解釋如何將分區組裝為 RAID 設備——創建和管理系統備份。這些都是 LFCS 認證中的必備知識。",-1)),e[29]||(e[29]=s("h3",{id:"瞭解raid",tabindex:"-1"},[t("瞭解RAID "),s("a",{class:"header-anchor",href:"#瞭解raid","aria-label":"Permalink to “瞭解RAID”"},"​")],-1)),e[30]||(e[30]=s("p",null,"這種被稱為獨立磁盤冗餘陣列（Redundant Array of Independent Disks）(RAID)的技術是將多個硬盤組合成一個單獨邏輯單元的存儲解決方案，它提供了數據冗餘功能並且改善硬盤的讀寫操作性能。",-1)),e[31]||(e[31]=s("p",null,"然而，實際的容錯和磁盤 I/O 性能硬盤取決於如何將多個硬盤組裝成磁盤陣列。根據可用的設備和容錯/性能的需求，RAID 被分為不同的級別，你可以參考 RAID 系列文章以獲得每個 RAID 級別更詳細的解釋。",-1)),s("ul",null,[s("li",null,[n(d,{href:"https://linux.cn/article-6085-1.html"},{default:p(()=>[...e[0]||(e[0]=[t("在 Linux 下使用 RAID（一）：介紹 RAID 的級別和概念",-1)])]),_:1})])]),e[32]||(e[32]=r(`<p>我們選擇用於創建、組裝、管理、監視軟件 RAID 的工具，叫做 mdadm (multiple disk admin 的簡寫）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- Debian 及衍生版 ----------------</span></span>
<span class="line"><span># aptitude update &amp;&amp; aptitude install mdadm</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- Red Hat 和基於 CentOS 的系統 ----------------</span></span>
<span class="line"><span># yum update &amp;&amp; yum install mdadm</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------------- openSUSE 上 ----------------</span></span>
<span class="line"><span># zypper refresh &amp;&amp; zypper install mdadm #</span></span></code></pre></div><h4 id="將分區組裝成-raid-設備" tabindex="-1">將分區組裝成 RAID 設備 <a class="header-anchor" href="#將分區組裝成-raid-設備" aria-label="Permalink to “將分區組裝成 RAID 設備”">​</a></h4><p>組裝已有分區作為 RAID 設備的過程由以下步驟組成。</p><p><strong>1. 使用 mdadm 創建陣列</strong></p><p>如果先前其中一個分區已經格式化，或者作為了另一個 RAID 陣列的一部分，你會被提示以確認創建一個新的陣列。假設你已經採取了必要的預防措施以避免丟失重要數據，那麼可以安全地輸入 Y 並且按下回車。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mdadm --create --verbose /dev/md0 --level=stripe --raid-devices=2 /dev/sdb1 /dev/sdc1</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Creating-RAID-Array.png" alt="Creating RAID Array"></p><p><em>創建 RAID 陣列</em></p><p><strong>2. 檢查陣列的創建狀態</strong></p><p>在創建了 RAID 陣列之後，你可以檢查使用以下命令檢查陣列的狀態。</p><pre><code># cat /proc/mdstat
or
# mdadm --detail /dev/md0    [More detailed summary]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Array-Status.png" alt="Check RAID Array Status"></p><p><em>檢查 RAID 陣列的狀態</em></p><p><strong>3. 格式化 RAID 設備</strong></p>`,17)),s("p",null,[e[2]||(e[2]=t("如本系列",-1)),n(d,{href:"https://linux.cn/article-7187-1.html"},{default:p(()=>[...e[1]||(e[1]=[t("第四講",-1)])]),_:1}),e[3]||(e[3]=t("所介紹的，按照你的需求/要求採用某種文件系統格式化你的設備。",-1))]),e[33]||(e[33]=r(`<p><strong>4. 監控 RAID 陣列服務</strong></p><p>讓監控服務時刻監視你的 RAID 陣列。把<code># mdadm --detail --scan</code>命令輸出結果添加到 <code>/etc/mdadm/mdadm.conf</code>(Debian及其衍生版)或者<code>/etc/mdadm.conf</code>(Cent0S/openSUSE)，如下。</p><pre><code># mdadm --detail --scan
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Monitor-RAID-Array.png" alt="Monitor RAID Array"></p><p><em>監控 RAID 陣列</em></p><pre><code># mdadm --assemble --scan     [Assemble the array]
</code></pre><p>為了確保服務能夠開機啓動，需要以 root 權限運行以下命令。</p><p><strong>Debian 及其衍生版</strong></p><p>Debian 及其衍生版能夠通過下面步驟使服務默認開機啓動：</p><pre><code># update-rc.d mdadm defaults
</code></pre><p>在 <code>/etc/default/mdadm</code> 文件中添加下面這一行</p><pre><code>AUTOSTART=true
</code></pre><p><strong>CentOS 和 openSUSE(systemd-based)</strong></p><pre><code># systemctl start mdmonitor
# systemctl enable mdmonitor
</code></pre><p><strong>CentOS 和 openSUSE(SysVinit-based)</strong></p><pre><code># service mdmonitor start
# chkconfig mdmonitor on
</code></pre><p><strong>5. 檢查RAID磁盤故障</strong></p><p>在支持冗餘的的 RAID 級別中，在需要時會替換故障的驅動器。當磁盤陣列中的設備出現故障時，僅當存在我們第一次創建陣列時預留的備用設備時，磁盤陣列會將自動啓動重建。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/Check-RAID-Faulty-Disk.png" alt="Check RAID Faulty Disk"></p><p><em>檢查 RAID 故障磁盤</em></p><p>否則，我們需要手動將一個額外的物理驅動器插入到我們的系統，並且運行。</p><pre><code># mdadm /dev/md0 --add /dev/sdX1
</code></pre><p>/dev/md0 是出現了問題的陣列，而 /dev/sdx1 是新添加的設備。</p><p><strong>6. 拆解一個工作陣列</strong></p><p>如果你需要使用工作陣列的設備創建一個新的陣列，你可能不得不去拆解已有工作陣列——(可選步驟)</p><pre><code># mdadm --stop /dev/md0                 #  Stop the array
# mdadm --remove /dev/md0             # Remove the RAID device
# mdadm --zero-superblock /dev/sdX1     # Overwrite the existing md superblock with zeroes
</code></pre><p><strong>7. 設置郵件通知</strong></p><p>你可以配置一個用於發送通知的有效郵件地址或者系統賬號(確保在 mdadm.conf 文件中有下面這一行)。——(可選步驟)</p><pre><code>MAILADDR root
</code></pre><p>在這種情況下，來自 RAID 後台監控程序所有的通知將會發送到你的本地 root 賬號的郵件箱中。其中一個類似的通知如下。</p><p>説明：此次通知事件和第5步中的例子相關。此處一個設備被標誌為錯誤，並且一個空閒的設備自動地被 mdadm 加入到陣列。我們用完了所有“健康的”空閒設備，因此我們得到了通知。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/RAID-Monitoring-Alerts.png" alt="RAID Monitoring Alerts"></p><p><em>RAID 監控通知</em></p><h4 id="瞭解-raid-級別" tabindex="-1">瞭解 RAID 級別 <a class="header-anchor" href="#瞭解-raid-級別" aria-label="Permalink to “瞭解 RAID 級別”">​</a></h4><p><strong>RAID 0</strong></p><p>陣列總大小是最小分區大小的 n 倍，n 是陣列中獨立磁盤的個數(你至少需要兩個驅動器/磁盤)。運行下面命令，使用 /dev/sdb1 和 /dev/sdc1 分區組裝一個 RAID 0 陣列。</p><pre><code># mdadm --create --verbose /dev/md0 --level=stripe --raid-devices=2 /dev/sdb1 /dev/sdc1
</code></pre><p>常見用途：用於支持性能比容錯更重要的實時應用程序的設置</p><p><strong>RAID 1 (又名鏡像)</strong></p><p>陣列總大小等於最小分區大小(你至少需要兩個驅動器/磁盤)。運行下面命令，使用 /dev/sdb1 和 /dev/sdc1 分區組裝一個 RAID 1 陣列。</p><pre><code># mdadm --create --verbose /dev/md0 --level=1 --raid-devices=2 /dev/sdb1 /dev/sdc1
</code></pre><p>常見用途：操作系統的安裝或者重要的子文件夾，例如 /home</p><p><strong>RAID 5 (又名奇偶校驗碼盤)</strong></p><p>陣列總大小將是最小分區大小的 (n-1) 倍。所減少的大小用於奇偶校驗(冗餘)計算(你至少需要3個驅動器/磁盤)。</p><p>説明：你可以指定一個空閒設備 (/dev/sde1) 替換問題出現時的故障部分(分區)。運行下面命令，使用 /dev/sdb1, /dev/sdc1, /dev/sdd1，/dev/sde1 組裝一個 RAID 5 陣列，其中 /dev/sde1 作為空閒分區。</p><pre><code># mdadm --create --verbose /dev/md0 --level=5 --raid-devices=3 /dev/sdb1 /dev/sdc1 /dev/sdd1 --spare-devices=1 /dev/sde1
</code></pre><p>常見用途：Web 和文件服務</p><p><strong>RAID 6 (又名雙重奇偶校驗碼盤)</strong></p><p>陣列總大小為(n<em>s)-2</em>s，其中n為陣列中獨立磁盤的個數，s為最小磁盤大小。</p><p>説明：你可以指定一個空閒分區(在這個例子為 /dev/sdf1)替換問題出現時的故障部分(分區)。</p><p>運行下面命令，使用 /dev/sdb1, /dev/sdc1, /dev/sdd1, /dev/sde1 和 /dev/sdf1 組裝 RAID 6 陣列，其中 /dev/sdf1 作為空閒分區。</p><pre><code># mdadm --create --verbose /dev/md0 --level=6 --raid-devices=4 /dev/sdb1 /dev/sdc1 /dev/sdd1 /dev/sde --spare-devices=1 /dev/sdf1
</code></pre><p>常見用途：大容量、高可用性要求的文件服務器和備份服務器。</p><p><strong>RAID 1+0 (又名鏡像條帶)</strong></p><p>因為 RAID 1+0 是 RAID 0 和 RAID 1 的組合，所以陣列總大小是基於兩者的公式計算的。首先，計算每一個鏡像的大小，然後再計算條帶的大小。</p><pre><code># mdadm --create --verbose /dev/md0 --level=10 --raid-devices=4 /dev/sd[b-e]1 --spare-devices=1 /dev/sdf1
</code></pre><p>常見用途：需要快速 IO 操作的資料庫和應用服務器</p><h4 id="創建和管理系統備份" tabindex="-1">創建和管理系統備份 <a class="header-anchor" href="#創建和管理系統備份" aria-label="Permalink to “創建和管理系統備份”">​</a></h4><p>記住， RAID 其所有的價值不是在於備份的替換者！在黑板上寫上1000次，如果你需要的話，但無論何時一定要記住它。在我們開始前，我們必須注意的是，沒有一個放之四海皆準的針對所有系統備份的解決方案，但這裏有一些東西，是你在規劃一個備份策略時需要考慮的。</p><ul><li>你的系統將用於什麼？(桌面或者服務器？如果系統是應用於後者，那麼最重要的服務是什麼？哪個配置是痛點？)</li><li>你每隔多久備份你的系統？</li><li>你需要備份的數據是什麼(比如文件/文件夾/資料庫轉儲)？你還可以考慮是否需要備份大型文件(比如音頻和視頻文件)。</li><li>這些備份將會存儲在哪裏(物理位置和媒體)？</li></ul><p><strong>備份你的數據</strong></p><p>方法1：使用 dd 命令備份整個磁盤。你可以在任意時間點通過創建一個準確的鏡像來備份一整個硬盤或者是分區。注意當設備是離線時，這種方法效果最好，也就是説它沒有被掛載並且沒有任何進程的 I/O 操作訪問它。</p><p>這種備份方法的缺點是鏡像將具有和磁盤或分區一樣的大小，即使實際數據佔用的是一個很小的比例。比如，如果你想要為只使用了10%的20GB的分區創建鏡像，那麼鏡像文件將仍舊是20GB。換句話來講，它不僅包含了備份的實際數據，而且也包含了整個分區。如果你想完整備份你的設備，那麼你可以考慮使用這個方法。</p><p><strong>從現有的設備創建一個鏡像文件</strong></p><pre><code># dd if=/dev/sda of=/system_images/sda.img
或者
--------------------- 可選地，你可以壓縮鏡像文件 -------------------
# dd if=/dev/sda | gzip -c &gt; /system_images/sda.img.gz
</code></pre><p><strong>從鏡像文件恢復備份</strong></p><pre><code># dd if=/system_images/sda.img of=/dev/sda
或者
--------------------- 根據你創建鏡像文件時的選擇(譯者注:比如壓縮) ----------------
# gzip -dc /system_images/sda.img.gz | dd of=/dev/sda
</code></pre>`,67)),s("p",null,[e[5]||(e[5]=t("方法2：使用 tar 命令備份確定的文件/文件夾——已經在本系列",-1)),n(d,{href:"https://linux.cn/article-7171-1.html"},{default:p(()=>[...e[4]||(e[4]=[t("第三講",-1)])]),_:1}),e[6]||(e[6]=t("中講了。如果你想要備份指定的文件/文件夾(配置文件，用户主目錄等等)，你可以使用這種方法。",-1))]),e[34]||(e[34]=r(`<p>方法3：使用 rsync 命令同步文件。rsync 是一種多功能遠程（和本地）文件複製工具。如果你想要從網絡設備備份或同步文件，rsync 是一種選擇。</p><p>無論是你是正在同步兩個本地文件夾還是本地 &lt; — &gt; 掛載在本地文件系統的遠程文件夾，其基本語法是一樣的。</p><pre><code># rsync -av source_directory destination_directory
</code></pre><p>在這裏，-a 遞歸遍歷子目錄(如果它們存在的話)，維持符號鏈接、時間戳、權限以及原本的屬主/屬組，-v 顯示詳細過程。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/rsync-synchronizing-Files.png" alt="rsync Synchronizing Files"></p><p><em>rsync 同步文件</em></p><p>除此之外，如果你想增加在網絡上傳輸數據的安全性，你可以通過 ssh 協議使用 rsync。</p><p><strong>通過 ssh 同步本地到遠程文件夾</strong></p><pre><code># rsync -avzhe ssh backups root@remote_host:/remote_directory/
</code></pre><p>這個示例，本地主機上的 backups 文件夾將與遠程主機上的 /root/remote_directory 的內容同步。</p><p>在這裏，-h 選項以易讀的格式顯示文件的大小，-e 標誌用於表示一個 ssh 連接。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/10/rsync-synchronize-Remote-Files.png" alt="rsync Synchronize Remote Files"></p><p><em>rsync 同步遠程文件</em></p><p><strong>通過ssh同步遠程到本地文件夾</strong></p><p>在這種情況下，交換前面示例中的 source 和 destination 文件夾。</p><pre><code># rsync -avzhe ssh root@remote_host:/remote_directory/ backups
</code></pre><p>請注意這些只是 rsync 用法的三個示例而已(你可能遇到的最常見的情形)。對於更多有關 rsync 命令的示例和用法 ，你可以查看下面的文章。</p>`,17)),s("ul",null,[s("li",null,[n(d,{href:"http://www.tecmint.com/rsync-local-remote-file-synchronization-commands/"},{default:p(()=>[...e[7]||(e[7]=[t("在 Linux 下同步文件的10個 rsync命令",-1)])]),_:1})])]),e[35]||(e[35]=s("h3",{id:"總結",tabindex:"-1"},[t("總結 "),s("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),e[36]||(e[36]=s("p",null,"作為一個系統管理員，你需要確保你的系統表現得儘可能好。如果你做好了充分準備，並且如果你的數據完整性能被諸如 RAID 和系統日常備份的存儲技術支持，那你將是安全的。",-1)),e[37]||(e[37]=s("p",null,"如果你有有關完善這篇文章的問題、評論或者進一步的想法，可以在下面暢所欲言。除此之外，請考慮通過你的社交網絡簡介分享這系列文章。",-1)),e[38]||(e[38]=s("hr",null,null,-1)),s("p",null,[e[9]||(e[9]=t("via: ",-1)),n(d,{href:"http://www.tecmint.com/creating-and-managing-raid-backups-in-linux/"},{default:p(()=>[...e[8]||(e[8]=[t("http://www.tecmint.com/creating-and-managing-raid-backups-in-linux/",-1)])]),_:1})]),s("p",null,[e[13]||(e[13]=t("作者：",-1)),n(d,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[10]||(e[10]=[t("Gabriel Cánepa",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),n(d,{href:"https://github.com/cposture"},{default:p(()=>[...e[11]||(e[11]=[t("cpsoture",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),n(d,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[18]||(e[18]=t("本文由 ",-1)),n(d,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創翻譯，",-1)),n(d,{href:"https://linux.cn/"},{default:p(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const R=i(m,[["render",g]]);export{I as __pageData,R as default};
